33	    33	    /// <summary>
34	    34	    /// Per-package session/credit history for the admin client profile: every ledger
35	    35	    /// movement on a package (class deductions, refunds, manual adjustments) resolved
36	    36	    /// to the class name/date/instructor, so staff can vet usage vs remaining credits.
37	    37	    /// </summary>
38	    38	    public async Task<object?> GetPackageSessionHistoryAsync(string packageId)
39	    39	    {
40	    40	        var pkg = await _clientPackages.Find(p => p.Id == packageId).FirstOrDefaultAsync();
41	    41	        if (pkg == null) return null;
42	    42	
43	    43	        var entries = await _ledger.Find(l => l.PackageInstanceId == packageId)
44	    44	            .SortByDescending(l => l.Timestamp).ToListAsync();
45	    45	
46	    46	        var rows = new List<object>();
47	    47	        foreach (var e in entries)
48	    48	        {
49	    49	            string? className = null; DateTime? sessionDate = null; string? instructor = null;
50	    50	            if (!string.IsNullOrWhiteSpace(e.ReferenceAttendanceId))
51	    51	            {
52	    52	                var att = await _attendances.Find(a => a.Id == e.ReferenceAttendanceId).FirstOrDefaultAsync();
53	    53	                if (att != null && !string.IsNullOrWhiteSpace(att.CalendarSessionId))
54	    54	                {
55	    55	                    var s = await _sessions.Find(x => x.Id == att.CalendarSessionId).FirstOrDefaultAsync();
56	    56	                    if (s != null) { className = s.ClassName; sessionDate = s.StartTime; instructor = s.InstructorName; }
57	    57	                }
58	    58	            }
59	    59	            rows.Add(new { timestamp = e.Timestamp, actionType = e.ActionType, amount = e.Amount, className, sessionDate, instructor, note = e.Notes });
60	    60	        }
61	    61	
62	    62	        return new
63	    63	        {
64	    64	            packageId = pkg.Id,
65	    65	            productName = $"{pkg.Format} package \u00b7 {pkg.TotalCredits} credits",
66	    66	            totalCredits = pkg.TotalCredits,
67	    67	            creditsUsed = pkg.CreditsUsed,
68	    68	            creditsRemaining = pkg.CreditsRemaining,
69	    69	            entries = rows,
70	    70	        };
71	    71	    }
