73	    73	    public async Task<IEnumerable<ClientPackage>> GetActivePackagesForClientAsync(string clientId, string format)
74	    74	    {
75	    75	        // A package with ExpiryDate == null never expires; include it unconditionally.
76	    76	        // A package with a concrete ExpiryDate must still be in the future.
77	    77	        var noExpiry  = Builders<ClientPackage>.Filter.Eq(p => p.ExpiryDate, (DateTime?)null);
78	    78	        var notExpired = Builders<ClientPackage>.Filter.Gt(p => p.ExpiryDate, DateTime.UtcNow);
79	    79	        var expiryOk  = Builders<ClientPackage>.Filter.Or(noExpiry, notExpired);
80	    80	
81	    81	        // MAT is a sub-type of group class. A MAT session can be paid with either a
82	    82	        // MAT-specific package (preferred — consumed first) or a generic GROUP package
83	    83	        // (fallback). Exact matches on other formats (PRIVATE, DUO, FREELANCE) are kept
84	    84	        // strict so packages are never cross-consumed across incompatible class types.
85	    85	        var upper = (format ?? "").ToUpperInvariant();
86	    86	        var formatFilter = upper == "MAT"
87	    87	            ? Builders<ClientPackage>.Filter.In(p => p.Format, new[] { "MAT", "GROUP" })
88	    88	            : Builders<ClientPackage>.Filter.Eq(p => p.Format, upper == "" ? format : upper);
89	    89	
90	    90	        var filter = Builders<ClientPackage>.Filter.And(
91	    91	            Builders<ClientPackage>.Filter.Eq(p => p.ClientId, clientId),
92	    92	            formatFilter,
93	    93	            // Include LOW_BALANCE alongside ACTIVE: a package with ≤2 credits
94	    94	            // remaining is still fully usable — excluding it would hide the
95	    95	            // PACKAGE_CREDIT option at checkout even though credits exist.
96	    96	            Builders<ClientPackage>.Filter.In(p => p.Status, new[] { "ACTIVE", "LOW_BALANCE" }),
97	    97	            Builders<ClientPackage>.Filter.Gt(p => p.CreditsRemaining, 0),
98	    98	            expiryOk
99	    99	        );
100	   100	
101	   101	        // For MAT sessions: sort MAT-specific packages before GROUP fallbacks so the
102	   102	        // specialised wallet is always consumed first. Within each bucket sort by
103	   103	        // earliest expiry (FIFO across wallets of the same type).
104	   104	        var packages = await _clientPackages.Find(filter).ToListAsync();
105	   105	        if (upper == "MAT")
106	   106	        {
107	   107	            packages = packages
108	   108	                .OrderBy(p => p.Format == "MAT" ? 0 : 1)
109	   109	                .ThenBy(p => p.ExpiryDate ?? DateTime.MaxValue)
110	   110	                .ToList();
111	   111	        }
112	   112	        else
113	   113	        {
114	   114	            packages = packages.OrderBy(p => p.ExpiryDate ?? DateTime.MaxValue).ToList();
115	   115	        }
116	   116	        return packages;
117	   117	    }
