126	   126	    public async Task<IEnumerable<ClientPackage>> GetAllActivePackagesAsync()
127	   127	    {
128	   128	        var now = DateTime.UtcNow;
129	   129	        var f = Builders<ClientPackage>.Filter;
130	   130	        var filter = f.And(
131	   131	            f.Gt(p => p.CreditsRemaining, 0),
132	   132	            f.Nin(p => p.Status, new[] { "EXPIRED", "CANCELLED", "DEPLETED" }),
133	   133	            f.Or(
134	   134	                f.Eq(p => p.ExpiryDate, (DateTime?)null),
135	   135	                f.Gt(p => p.ExpiryDate, now)));
136	   136	        return await _clientPackages.Find(filter)
137	   137	            .SortBy(p => p.ExpiryDate)
138	   138	            .ToListAsync();
139	   139	    }
