141	   141	    /// <summary>
142	   142	    /// Deducts one credit/slot from the oldest-expiring active <see cref="ClientPackage"/> of the
143	   143	    /// requested <paramref name="format"/> for the given client.
144	   144	    /// Accepted formats: <c>"GROUP"</c>, <c>"PRIVATE"</c>, and (since P3-S13) <c>"FREELANCE"</c> —
145	   145	    /// the same FIFO + low-balance + completed lifecycle applies regardless of format.
146	   146	    /// <para>
147	   147	    /// <paramref name="quantity"/> (Issue #3, default 1) deducts multiple credits in one call —
148	   148	    /// e.g. a group-class multi-seat reservation. Credits are taken FIFO across the customer's
149	   149	    /// active wallets of the format; the deduction may therefore span more than one wallet.
150	   150	    /// Returns <c>false</c> if the customer has fewer than <paramref name="quantity"/> credits
151	   151	    /// total — in that case no partial deduction is applied (atomic at the request level).
152	   152	    /// </para>
153	   153	    /// </summary>
154	   154	    public async Task<bool> DeductCreditAsync(string clientId, string format, string referenceAttendanceId, int quantity = 1)
155	   155	    {
156	   156	        if (quantity <= 0) quantity = 1;
157	   157	
158	   158	        var activePackages = (await GetActivePackagesForClientAsync(clientId, format)).ToList();
159	   159	        var totalAvailable = activePackages.Sum(p => p.CreditsRemaining);
160	   160	        if (totalAvailable < quantity) return false;
161	   161	
162	   162	        var remainingToDeduct = quantity;
163	   163	        foreach (var pkg in activePackages)
164	   164	        {
165	   165	            if (remainingToDeduct <= 0) break;
166	   166	
167	   167	            var take = Math.Min(pkg.CreditsRemaining, remainingToDeduct);
168	   168	            pkg.CreditsRemaining -= take;
169	   169	            pkg.CreditsUsed += take;
170	   170	
171	   171	            if (pkg.CreditsRemaining == 0) pkg.Status = "COMPLETED";
172	   172	            else if (pkg.CreditsRemaining <= 2) pkg.Status = "LOW_BALANCE";
173	   173	
174	   174	            await _clientPackages.ReplaceOneAsync(p => p.Id == pkg.Id, pkg);
175	   175	
176	   176	            var log = new PackageLedgerLog
177	   177	            {
178	   178	                PackageInstanceId = pkg.Id ?? "",
179	   179	                ActionType = "DEDUCTION",
180	   180	                Amount = -take,
181	   181	                ReferenceAttendanceId = referenceAttendanceId
182	   182	            };
183	   183	            await _ledger.InsertOneAsync(log);
184	   184	
185	   185	            remainingToDeduct -= take;
186	   186	        }
187	   187	
188	   188	        return true;
189	   189	    }
190	   190	
191	   191	    /// <summary>
192	   192	    /// Refunds <paramref name="quantity"/> credits (default 1) back to the named
193	   193	    /// <see cref="ClientPackage"/>. For multi-seat group cancellations the caller may need
194	   194	    /// to invoke this once per source wallet if the original deduction spanned multiple
195	   195	    /// wallets; the ledger log preserves which wallet each unit came from.
196	   196	    /// </summary>
197	   197	    public async Task<bool> RefundCreditAsync(string packageInstanceId, string referenceAttendanceId, int quantity = 1)
198	   198	    {
199	   199	        if (quantity <= 0) quantity = 1;
200	   200	
201	   201	        var pkg = await _clientPackages.Find(p => p.Id == packageInstanceId).FirstOrDefaultAsync();
202	   202	        if (pkg == null) return false;
203	   203	
204	   204	        pkg.CreditsRemaining += quantity;
205	   205	        pkg.CreditsUsed -= quantity;
206	   206	        if (pkg.CreditsUsed < 0) pkg.CreditsUsed = 0; // defensive: never go negative
207	   207	
208	   208	        if (pkg.Status == "COMPLETED" && pkg.CreditsRemaining > 0)
209	   209	        {
210	   210	            pkg.Status = "ACTIVE";
211	   211	        }
212	   212	
213	   213	        await _clientPackages.ReplaceOneAsync(p => p.Id == pkg.Id, pkg);
214	   214	
215	   215	        var log = new PackageLedgerLog
216	   216	        {
217	   217	            PackageInstanceId = pkg.Id ?? "",
218	   218	            ActionType = "REFUND",
219	   219	            Amount = quantity,
220	   220	            ReferenceAttendanceId = referenceAttendanceId
221	   221	        };
222	   222	        await _ledger.InsertOneAsync(log);
223	   223	
224	   224	        return true;
225	   225	    }
226	   226	
227	   227	    /// <summary>
228	   228	    /// Multi-wallet refund driven by the ledger. Walks every <c>DEDUCTION</c> row
229	   229	    /// tagged with <paramref name="attendanceId"/> and reverses each one against its
230	   230	    /// originating wallet — necessary because a single PACKAGE_CREDIT booking can
231	   231	    /// span more than one <see cref="ClientPackage"/> when FIFO crosses a wallet
232	   232	    /// boundary (e.g. 2-seat group class drawing 1 credit from each of two wallets).
233	   233	    /// Idempotent: a second call after every DEDUCTION has been matched by a REFUND
234	   234	    /// of equal or greater magnitude is a no-op (returns <c>false</c>).
235	   235	    /// </summary>
236	   236	    public async Task<bool> RefundCreditByAttendanceAsync(string attendanceId)
237	   237	    {
238	   238	        var (refundedAny, _) = await RefundCreditByAttendanceWithTrailAsync(attendanceId);
239	   239	        return refundedAny;
240	   240	    }
241	   241	
242	   242	    /// <summary>
243	   243	    /// SPM-108 — ledger-driven refund that also reports whether ANY ledger trail
244	   244	    /// (deduction or prior refund) exists for this attendance.
245	   245	    /// <para>
246	   246	    /// Returns <c>(refunded, hasLedgerTrail)</c>:
247	   247	    /// <list type="bullet">
248	   248	    ///   <item><c>refunded</c> — true when at least one credit was actually
249	   249	    ///   returned by THIS call (i.e. a wallet still had a net-negative position).</item>
250	   250	    ///   <item><c>hasLedgerTrail</c> — true when one or more ledger rows reference
251	   251	    ///   this attendance, regardless of net. Callers use this to decide whether the
252	   252	    ///   legacy non-ledger <see cref="RefundCreditAsync"/> fallback is safe: a trail
253	   253	    ///   exists means this booking has already been accounted for in the ledger, so
254	   254	    ///   the blind +1 fallback MUST NOT run (it would phantom-refund a credit, e.g.
255	   255	    ///   the owner-reported 1 -> 2 on a re-cancel where the net was already 0).</item>
256	   256	    /// </list>
257	   257	    /// </para>
258	   258	    /// </summary>
259	   259	    public async Task<(bool refunded, bool hasLedgerTrail)> RefundCreditByAttendanceWithTrailAsync(string attendanceId)
260	   260	    {
261	   261	        if (string.IsNullOrWhiteSpace(attendanceId)) return (false, false);
262	   262	
263	   263	        var entries = await _ledger
264	   264	            .Find(l => l.ReferenceAttendanceId == attendanceId)
265	   265	            .ToListAsync();
266	   266	        if (entries.Count == 0) return (false, false);
267	   267	
268	   268	        // Net per-wallet position: sum of all ledger rows. Positive/zero net means the
269	   269	        // wallet has already been refunded; we only want to refund where net < 0
270	   270	        // (i.e. credits still consumed by this attendance). This is what makes the
271	   271	        // refund idempotent — a second call after a full refund finds no net-negative
272	   272	        // wallet and returns refunded=false WITHOUT writing another REFUND row.
273	   273	        var netByWallet = entries
274	   274	            .GroupBy(e => e.PackageInstanceId)
275	   275	            .Select(g => new { PackageInstanceId = g.Key, Net = g.Sum(e => e.Amount) })
276	   276	            .Where(x => x.Net < 0)
277	   277	            .ToList();
278	   278	
279	   279	        if (netByWallet.Count == 0) return (false, true); // trail exists, nothing left to refund
280	   280	
281	   281	        var refundedAny = false;
282	   282	        foreach (var w in netByWallet)
283	   283	        {
284	   284	            var qty = -w.Net; // flip the negative net into a positive refund quantity
285	   285	            var ok = await RefundCreditAsync(w.PackageInstanceId, attendanceId, qty);
286	   286	            refundedAny |= ok;
287	   287	        }
288	   288	        return (refundedAny, true);
289	   289	    }
290	   290	
291	   291	    /// <summary>
292	   292	    /// SPM-110 — refund AT MOST <paramref name="seatsToRefund"/> credits for the attendance,
293	   293	    /// for the per-seat cancel of a multi-seat group booking. Mirrors the idempotent,
294	   294	    /// over-refund-safe net-by-wallet logic of <see cref="RefundCreditByAttendanceWithTrailAsync"/>
295	   295	    /// but caps the total returned at the requested seat count.
296	   296	    /// </summary>
297	   297	    public async Task<(int refundedCount, bool hasLedgerTrail)> RefundPartialCreditByAttendanceWithTrailAsync(string attendanceId, int seatsToRefund)
298	   298	    {
299	   299	        if (string.IsNullOrWhiteSpace(attendanceId)) return (0, false);
300	   300	        if (seatsToRefund <= 0) return (0, false);
301	   301	
302	   302	        var entries = await _ledger
303	   303	            .Find(l => l.ReferenceAttendanceId == attendanceId)
304	   304	            .ToListAsync();
305	   305	        if (entries.Count == 0) return (0, false);
306	   306	
307	   307	        // Per-wallet net position, identical bookkeeping to the full-cancel path:
308	   308	        // only wallets still net-negative have credits consumed by this attendance
309	   309	        // that can be returned. This is what keeps the partial refund idempotent —
310	   310	        // a second call after seats were already returned sees a smaller net and
311	   311	        // will not over-refund.
312	   312	        var netByWallet = entries
313	   313	            .GroupBy(e => e.PackageInstanceId)
314	   314	            .Select(g => new { PackageInstanceId = g.Key, Net = g.Sum(e => e.Amount) })
315	   315	            .Where(x => x.Net < 0)
316	   316	            .ToList();
317	   317	
318	   318	        if (netByWallet.Count == 0) return (0, true); // trail exists, nothing left to refund
319	   319	
320	   320	        var remainingToRefund = seatsToRefund;
321	   321	        var refundedCount = 0;
322	   322	        foreach (var w in netByWallet)
323	   323	        {
324	   324	            if (remainingToRefund <= 0) break;
325	   325	
326	   326	            // Cap this wallet's refund at the smaller of (credits it still owes) and
327	   327	            // (seats we have left to return) so we never exceed the requested count.
328	   328	            var available = -w.Net; // positive credits still consumed on this wallet
329	   329	            var qty = Math.Min(available, remainingToRefund);
330	   330	            if (qty <= 0) continue;
331	   331	
332	   332	            var ok = await RefundCreditAsync(w.PackageInstanceId, attendanceId, qty);
333	   333	            if (ok)
334	   334	            {
335	   335	                refundedCount += qty;
336	   336	                remainingToRefund -= qty;
337	   337	            }
338	   338	        }
339	   339	
340	   340	        return (refundedCount, true);
341	   341	    }
342	   342	
343	   343	    /// <summary>
344	   344	    /// SPM-110 — neutralise the ledger net for up to <paramref name="seatsForfeited"/>
345	   345	    /// seats of a late-cancelled PACKAGE_CREDIT booking WITHOUT touching wallet balances
346	   346	    /// (the credits stay consumed — that's the forfeit). Writes ledger-only FORFEIT rows
347	   347	    /// so the per-wallet net reflects the seats still genuinely owed, preventing a later
348	   348	    /// cancel of the booking's remaining seats from over-refunding the forfeited ones.
349	   349	    /// </summary>
350	   350	    public async Task<int> ForfeitCreditByAttendanceAsync(string attendanceId, int seatsForfeited)
351	   351	    {
352	   352	        if (string.IsNullOrWhiteSpace(attendanceId)) return 0;
353	   353	        if (seatsForfeited <= 0) return 0;
354	   354	
355	   355	        var entries = await _ledger
356	   356	            .Find(l => l.ReferenceAttendanceId == attendanceId)
357	   357	            .ToListAsync();
358	   358	        if (entries.Count == 0) return 0;
359	   359	
360	   360	        var netByWallet = entries
361	   361	            .GroupBy(e => e.PackageInstanceId)
362	   362	            .Select(g => new { PackageInstanceId = g.Key, Net = g.Sum(e => e.Amount) })
363	   363	            .Where(x => x.Net < 0)
364	   364	            .ToList();
365	   365	
366	   366	        if (netByWallet.Count == 0) return 0;
367	   367	
368	   368	        var remaining = seatsForfeited;
369	   369	        var forfeited = 0;
370	   370	        foreach (var w in netByWallet)
371	   371	        {
372	   372	            if (remaining <= 0) break;
373	   373	
374	   374	            var available = -w.Net; // credits still net-consumed on this wallet
375	   375	            var qty = Math.Min(available, remaining);
376	   376	            if (qty <= 0) continue;
377	   377	
378	   378	            // Ledger-only positive row: raises the net toward zero so these seats can't
379	   379	            // be refunded later, but deliberately does NOT modify the ClientPackage
380	   380	            // (the customer forfeited these credits by cancelling late).
381	   381	            var log = new PackageLedgerLog
382	   382	            {
383	   383	                PackageInstanceId = w.PackageInstanceId,
384	   384	                ActionType = "FORFEIT",
385	   385	                Amount = qty,
386	   386	                ReferenceAttendanceId = attendanceId,
387	   387	                Notes = "Late-cancel seat forfeit (SPM-110) — credit not returned to wallet.",
388	   388	            };
389	   389	            await _ledger.InsertOneAsync(log);
390	   390	
391	   391	            forfeited += qty;
392	   392	            remaining -= qty;
393	   393	        }
394	   394	
395	   395	        return forfeited;
396	   396	    }
