398	   398	    public async Task ExpireOldPackagesAsync()
399	   399	    {
400	   400	        // Only expire packages that have a concrete ExpiryDate in the past.
401	   401	        // Packages with ExpiryDate == null are open-ended and must never be swept.
402	   402	        var filter = Builders<ClientPackage>.Filter.And(
403	   403	            Builders<ClientPackage>.Filter.In(p => p.Status, new[] { "ACTIVE", "LOW_BALANCE" }),
404	   404	            Builders<ClientPackage>.Filter.Ne(p => p.ExpiryDate, (DateTime?)null),
405	   405	            Builders<ClientPackage>.Filter.Lt(p => p.ExpiryDate, DateTime.UtcNow)
406	   406	        );
407	   407	
408	   408	        var update = Builders<ClientPackage>.Update.Set(p => p.Status, "EXPIRED");
409	   409	        await _clientPackages.UpdateManyAsync(filter, update);
410	   410	    }
411	   411	
412	   412	    public async Task FreezePackageAsync(string packageInstanceId, DateTime freezeStart, int daysToFreeze, string? reason)
413	   413	    {
414	   414	        var pkg = await _clientPackages.Find(p => p.Id == packageInstanceId).FirstOrDefaultAsync();
415	   415	        if (pkg == null) throw new Exception("Package not found.");
416	   416	
417	   417	        // Extend expiry by freeze duration
418	   418	        if (pkg.ExpiryDate.HasValue)
419	   419	        {
420	   420	            pkg.ExpiryDate = pkg.ExpiryDate.Value.AddDays(daysToFreeze);
421	   421	        }
422	   422	        pkg.Status = "FROZEN";
423	   423	        await _clientPackages.ReplaceOneAsync(p => p.Id == pkg.Id, pkg);
424	   424	
425	   425	        // Log the freeze
426	   426	        var freeze = new PackageFreeze
427	   427	        {
428	   428	            PackageInstanceId = packageInstanceId,
429	   429	            FreezeStartDate = freezeStart,
430	   430	            FreezeEndDate = freezeStart.AddDays(daysToFreeze),
431	   431	            DaysAddedToExpiry = daysToFreeze,
432	   432	            Reason = reason
433	   433	        };
434	   434	        await _freezes.InsertOneAsync(freeze);
435	   435	    }
436	   436	
437	   437	    /// <summary>
438	   438	    /// Manually adjust credits on a specific <see cref="ClientPackage"/> by a signed
439	   439	    /// <paramref name="delta"/>. Positive delta adds credits (gift / compassionate refund);
440	   440	    /// negative removes them (manual forfeit).
441	   441	    /// <para>
442	   442	    /// When adding credits, <see cref="ClientPackage.TotalCredits"/> is increased by the
