462	   462	
463	   463	        // Guard: adjustments on frozen or expired packages are not allowed.
464	   464	        // The admin should unfreeze (or extend expiry) first — otherwise the
465	   465	        // status-recalculation logic below would silently overwrite FROZEN →
466	   466	        // COMPLETED or leave stranded credits on an EXPIRED package that won't
467	   467	        // appear in active-wallet queries.
468	   468	        if (pkg.Status is "FROZEN" or "EXPIRED") return false;
469	   469	
470	   470	        // Guard: can't remove more credits than the package currently holds.
471	   471	        if (delta < 0 && pkg.CreditsRemaining < Math.Abs(delta)) return false;
472	   472	
473	   473	        // Capture before-state for audit.
474	   474	        var beforeRemaining = pkg.CreditsRemaining;
475	   475	        var beforeUsed = pkg.CreditsUsed;
476	   476	        var beforeTotal = pkg.TotalCredits;
477	   477	        var beforeStatus = pkg.Status;
478	   478	
479	   479	        // Apply the adjustment.
480	   480	        pkg.CreditsRemaining += delta;
481	   481	        if (delta > 0)
482	   482	        {
483	   483	            // Adding credits back: reduce CreditsUsed (we're returning consumed
484	   484	            // credits, not expanding the package capacity). TotalCredits must
485	   485	            // stay at the original product capacity so renewals, the credit bar,
486	   486	            // and the wallet label always reflect the purchased package size.
487	   487	            pkg.CreditsUsed -= delta;
488	   488	            if (pkg.CreditsUsed < 0) pkg.CreditsUsed = 0; // defensive: never go negative
489	   489	        }
490	   490	        else
491	   491	        {
492	   492	            // Removing credits: reflect the removal in CreditsUsed.
493	   493	            pkg.CreditsUsed += Math.Abs(delta);
494	   494	        }
495	   495	
496	   496	        // Recalculate status — mirrors the same rules as DeductCreditAsync.
497	   497	        if (pkg.CreditsRemaining == 0)
498	   498	            pkg.Status = "COMPLETED";
499	   499	        else if (pkg.CreditsRemaining <= 2)
500	   500	            pkg.Status = "LOW_BALANCE";
501	   501	        else if (pkg.Status is "COMPLETED" or "LOW_BALANCE")
502	   502	            pkg.Status = "ACTIVE";
503	   503	
504	   504	        await _clientPackages.ReplaceOneAsync(p => p.Id == pkg.Id, pkg);
505	   505	
506	   506	        // ── Ledger row ────────────────────────────────────────────────────
507	   507	        // ActionType = "MANUAL_ADJUSTMENT" (a new enum value in the comment
508	   508	        // set of PackageLedgerLog). Notes carries the admin's stated reason.
509	   509	        var log = new PackageLedgerLog
510	   510	        {
511	   511	            PackageInstanceId = pkg.Id ?? "",
512	   512	            ActionType = "MANUAL_ADJUSTMENT",
513	   513	            Amount = delta,
514	   514	            ReferenceAttendanceId = null,
515	   515	            Notes = reason,
516	   516	        };
517	   517	        await _ledger.InsertOneAsync(log);
518	   518	
519	   519	        // ── Governance audit row ──────────────────────────────────────────
520	   520	        // Non-throwing per the IAuditLogger contract — business transaction
521	   521	        // is never rolled back if audit storage fails.
522	   522	        await _auditLogger.LogAsync(
523	   523	            action: "MANUAL_CREDIT_ADJUSTMENT",
524	   524	            entityType: "ClientPackage",
525	   525	            entityId: pkg.Id ?? "",
526	   526	            entityLabel: $"{pkg.Format} package · {beforeTotal} credits",
527	   527	            before: new
528	   528	            {
529	   529	                creditsRemaining = beforeRemaining,
530	   530	                creditsUsed = beforeUsed,
531	   531	                totalCredits = beforeTotal,
532	   532	                status = beforeStatus,
533	   533	            },
534	   534	            after: new
