537	   537	                creditsUsed = pkg.CreditsUsed,
538	   538	                totalCredits = pkg.TotalCredits,
539	   539	                status = pkg.Status,
540	   540	            },
541	   541	            metadata: new { reason, delta });
542	   542	
543	   543	        return true;
544	   544	    }
