589	   589	            entityLabel: $"{pkg.Format} package · {pkg.TotalCredits} credits",
590	   590	            before: new { expiryDate = oldExpiry, status = oldStatus },
591	   591	            after:  new { expiryDate = pkg.ExpiryDate, status = pkg.Status },
592	   592	            metadata: new { reason });
