        .SortBy(a => a.BookedAt)
        .ToListAsync();
}

public async Task<IEnumerable<SessionRosterDto>> GetSessionRosterAsync(string sessionId)
{
    var attendances = await _attendances
        .Find(a => a.CalendarSessionId == sessionId && a.Status != "CANCELLED")
        .SortBy(a => a.BookedAt)
        .ToListAsync();
    if (attendances.Count == 0) return new List<SessionRosterDto>();

    // Invoice reconciliation — Attendance payment fields can be stale when the
    // balance was settled through the POS invoice-payment flow, so a PAID
    // linked invoice is the source of truth (mirrors GetSessionBookings above).
    var attIds = attendances.Select(a => a.Id!).ToList();
    var invoiceStatusMap = new Dictionary<string, (string status, decimal totalNet)>();
    var linkedInvoices = await _invoices.Find(
        Builders<Invoice>.Filter.ElemMatch(i => i.Lines,
            Builders<InvoiceLine>.Filter.In(l => l.AttendanceId, attIds))
    ).ToListAsync();
    foreach (var inv in linkedInvoices)
        foreach (var line in inv.Lines.Where(l => !string.IsNullOrWhiteSpace(l.AttendanceId)))
            if (!invoiceStatusMap.ContainsKey(line.AttendanceId!))
                invoiceStatusMap[line.AttendanceId!] = (inv.Status, inv.TotalNet);

    return attendances.Select(att =>
    {
        var paid = att.AmountPaid ?? 0m;
        var due = att.AmountDueAtStudio ?? 0m;
        if (invoiceStatusMap.TryGetValue(att.Id!, out var invStatus) && invStatus.status == "PAID")
        {
            paid = invStatus.totalNet;
            due = 0m;
        }

        string payStatus;
        if (att.IsFreeClass) payStatus = "free";
        else if (att.PaymentMethod == "PACKAGE_CREDIT") payStatus = "package";
        else if (due <= 0) payStatus = "paid";
        else if (paid > 0 && due > 0) payStatus = "partial";
        else payStatus = "unpaid";

        // Only an ACTIVE attendee with an outstanding balance still owes; free
        // and PACKAGE_CREDIT are settled, and NO_SHOW / LATE_CANCEL aren't
        // collectable (CANCELLED is already excluded from the roster query).
        var isActive = att.Status != "NO_SHOW" && att.Status != "LATE_CANCEL";
        var stillOwes = isActive && (payStatus == "unpaid" || payStatus == "partial");

        return new SessionRosterDto
        {
            Id = att.Id!,
            ClientId = att.ClientId,
            ClientName = att.ClientName,
            ClientPhone = att.ClientPhone,
            Status = att.Status,
            Quantity = att.Quantity,
            BookingSource = att.BookingSource,
            PaymentStatus = payStatus,
            StillOwes = stillOwes,
        };
    }).ToList();
}

/// <summary>
/// Hard-removes a single attendee from a class (for booking mistakes). Refunds
/// any package credit that was consumed, deletes the attendance row entirely,
/// and frees the seat(s) on the session. Unlike a CANCELLED status this leaves
/// no lingering row on the roster.
/// </summary>
public async Task<bool> RemoveAttendanceAsync(string attendanceId)
{
    var att = await _attendances.Find(a => a.Id == attendanceId).FirstOrDefaultAsync();
    if (att is null) return false;

    // Refund any consumed package credit — ledger-driven, with the legacy
    // PackageInstanceId fallback (mirrors the session-cancel refund path).
    var (refunded, hasLedgerTrail) = await _walletService.RefundCreditByAttendanceWithTrailAsync(att.Id!);
    if (!refunded && !hasLedgerTrail && !string.IsNullOrEmpty(att.PackageInstanceId))
        await _walletService.RefundCreditAsync(
            att.PackageInstanceId, att.RescheduledFromAttendanceId ?? att.Id!);

    // Delete the row and free the seat(s).
    await _attendances.DeleteOneAsync(a => a.Id == attendanceId);
    if (!string.IsNullOrWhiteSpace(att.CalendarSessionId))
    {
        var seats = att.Quantity <= 0 ? 1 : att.Quantity;
        await _sessions.UpdateOneAsync(
            s => s.Id == att.CalendarSessionId,
            Builders<CalendarSession>.Update.Inc(s => s.CurrentBookings, -seats));
        // Never let the counter go negative.
        await _sessions.UpdateOneAsync(
            s => s.Id == att.CalendarSessionId && s.CurrentBookings < 0,
            Builders<CalendarSession>.Update.Set(s => s.CurrentBookings, 0));
        // SPM-98 — if this was a duo PRIVATE whose Capacity was bumped 1→2 and no
        // active seats remain, restore Capacity to 1 so the freed 1-on-1 slot
        // can't later be double-booked by two unrelated single bookers.
        await RestorePrivateCapacityIfEmptyAsync(att.CalendarSessionId);
    }
    return true;
}

