private async Task<string?> ResolveFreelancePackageIdAsync(
    string? packageId,
    string? staffId,
    string format,
    int creditsNeeded)
{
    if (!string.IsNullOrWhiteSpace(packageId))
        return packageId;

    if (string.IsNullOrWhiteSpace(staffId))
        return null;

    var staff = await _staff.Find(s => s.Id == staffId).FirstOrDefaultAsync();
    if (staff == null || !string.Equals(staff.Role, "FREELANCE", StringComparison.OrdinalIgnoreCase))
        return null;
    if (string.IsNullOrWhiteSpace(staff.StudioRentalClientId))
        return null;

    var noExpiry = Builders<ClientPackage>.Filter.Eq(p => p.ExpiryDate, (DateTime?)null);
    var notExpired = Builders<ClientPackage>.Filter.Gt(p => p.ExpiryDate, DateTime.UtcNow);
    var filter = Builders<ClientPackage>.Filter.And(
        Builders<ClientPackage>.Filter.Eq(p => p.ClientId, staff.StudioRentalClientId),
        Builders<ClientPackage>.Filter.Eq(p => p.Format, format),
        Builders<ClientPackage>.Filter.In(p => p.Status, new[] { "ACTIVE", "LOW_BALANCE" }),
        Builders<ClientPackage>.Filter.Gt(p => p.CreditsRemaining, 0),
        Builders<ClientPackage>.Filter.Or(noExpiry, notExpired)
    );

    var packages = await _clientPackages.Find(filter)
        .SortBy(p => p.ExpiryDate)
        .ThenBy(p => p.ActivationDate)
        .ToListAsync();

    return packages
        .FirstOrDefault(p => creditsNeeded <= 0 || p.CreditsRemaining >= creditsNeeded)
        ?.Id;
}

